// writeSeries emits one HELP line, one TYPE line, then one sample
// line per non-zero counter. The labels slice declares the label
// names in the order they should appear; the counterKey fields are
// read positionally via labelValue.
func writeSeries(w io.Writer, name, help string, m map[counterKey]*uint64, labels []string) (int64, error) {
	var total int64
	// Always emit HELP/TYPE so scrapers see the metric family even
	// when no samples have been recorded yet.
	n, err := fmt.Fprintf(w, "# HELP %s %s\n# TYPE %s counter\n", name, help, name)
	if err != nil {
		return total + int64(n), err
	}
	total += int64(n)
	if len(m) == 0 {
		return total, nil
	}
	// Collect and sort keys for deterministic output.
	keys := make([]counterKey, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		return keyLess(keys[i], keys[j], labels)
	})
	for _, k := range keys {
		v := atomic.LoadUint64(m[k])
		n, err := fmt.Fprintf(w, "%s%s %d\n", name, formatLabels(k, labels), v)
		if err != nil {
			return total + int64(n), err
		}
		total += int64(n)
	}
	return total, nil
}

// writeRejectionSeries emits a string-keyed counter family using the
// "reason" label. It is a thin wrapper around writeStringKeySeries kept
// for call-site readability. Output is sorted by key for deterministic
// scrape diffs.
func writeRejectionSeries(w io.Writer, name, help string, m map[string]*uint64) (int64, error) {
	return writeStringKeySeries(w, name, help, "reason", m)
}

// writeStringKeySeries emits a string-keyed counter family with a single
// label dimension whose name is given by label. Output is sorted by key
// for deterministic scrape diffs.
func writeStringKeySeries(w io.Writer, name, help, label string, m map[string]*uint64) (int64, error) {
	var total int64
	n, err := fmt.Fprintf(w, "# HELP %s %s\n# TYPE %s counter\n", name, help, name)
	if err != nil {
		return total + int64(n), err
	}
	total += int64(n)
	if len(m) == 0 {
		return total, nil
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		v := atomic.LoadUint64(m[k])
		n, err := fmt.Fprintf(w, "%s{%s=\"%s\"} %d\n", name, label, sanitizeLabel(k), v)
		if err != nil {
			return total + int64(n), err
		}
		total += int64(n)
	}
	return total, nil
}

// writeFusionSeries emits the nexus_fusion_arbiter_total family (issue #187).
